pub(crate) const STYLES: &str = r#"
.df-character-display .character-hero{padding:125px 0 35px;text-align:center}.df-character-display .character-description{margin:0 auto;max-width:650px}.df-character-display h1{font-size:clamp(42px,5vw,76px);max-width:1000px;margin:12px auto 18px}.df-character-display .display-report{display:flex;align-items:center;justify-content:center;gap:18px;margin-top:25px;flex-wrap:wrap}.df-character-display .display-readiness{font:11px/1.6 system-ui,sans-serif;color:#ebcd91;border:1px solid #cba46673;border-radius:6px;background:#24211bee;padding:9px 16px;box-shadow:inset 0 1px 0 #fff1;margin:0}.df-character-display .display-progress{font:12px/1.6 system-ui,sans-serif;color:#d8cbb2;margin:0}.df-character-display .display-notice{font:11px/1.6 system-ui,sans-serif;color:#c5b99e;min-height:24px;max-width:720px;margin:15px auto 0}.df-character-display[data-connection=offline] .display-notice,.df-character-display[data-connection=reconnecting] .display-notice{color:#dcc393}.df-character-display .display-roster{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(230px,100%),1fr));gap:20px;width:min(1180px,92%);margin:0 auto 40px;align-items:stretch}.df-character-display .display-member{position:relative;border:1px solid #c7a86b4d;border-radius:10px;background:linear-gradient(135deg,#24211bee,#181713f5);padding:20px;text-align:center;box-shadow:0 16px 45px #0004}.df-character-display .display-portrait{height:260px;margin:0 0 18px;border-radius:6px}.df-character-display .display-member-name{font-size:26px;font-weight:400;color:#f1dfbd;margin:0 0 12px}.df-character-display .display-member-readiness{font:10px/1.6 system-ui,sans-serif;letter-spacing:.5px;color:#b4aca0;margin:0 0 12px}.df-character-display .display-member-progress{font:11px/1.6 system-ui,sans-serif;color:#d8cbb2;margin:0;padding-top:12px;border-top:1px solid #d9b77a24}.df-character-display .display-member[data-readiness=ready],.df-character-display .display-member[data-readiness=locked]{border-color:#82b79b88;box-shadow:0 16px 45px #0004,inset 0 3px 0 #82b79b88}.df-character-display .display-member[data-readiness=ready] .display-member-readiness,.df-character-display .display-member[data-readiness=locked] .display-member-readiness{color:#b5ddc2}.df-character-display .display-host-offers{width:min(1000px,92%);margin:0 auto 30px;display:flex;justify-content:center;flex-wrap:wrap;gap:12px}.df-character-display .display-host-offers button{width:auto;min-width:220px}.df-character-display .display-fixture-controls{width:min(1380px,92%);margin:0 auto 24px;display:flex;gap:10px;flex-wrap:wrap}.df-character-display .display-fixture-controls button{width:auto}.df-character-display .display-fixture-output{width:min(1380px,92%);margin:0 auto 24px;font:12px/1.7 system-ui,sans-serif;color:#b4aca0}
.df-character-display .display-host-offers button:enabled{background:linear-gradient(135deg,#e3c592,#b99151);color:#211b11;border-color:#e9c78d;font-weight:650;box-shadow:0 5px 20px #9f6b3026,inset 0 1px 0 #fff6}.df-character-display .display-host-offers button:hover:enabled{background:#edcea0}.df-character-display[data-readiness=ready] .display-readiness,.df-character-display[data-readiness=locked] .display-readiness{color:#b5ddc2;border-color:#82b79b88}
.df-character-display .display-member-appearance{font:14px/1.5 system-ui,sans-serif;color:#ead7b4;margin:0 0 12px;padding:10px 12px;border:1px solid #c7a86b66;border-radius:6px;background:#11110eaa}.df-character-display .display-member-appearance[hidden]{display:none}
@media(min-width:1800px){.df-character-display .character-hero{padding-top:80px}.df-character-display .display-roster{gap:24px;margin-bottom:20px}.df-character-display .display-member{padding:18px}.df-character-display .display-portrait{height:240px}}
@media(max-width:700px){.df-character-display h1{font-size:37px;letter-spacing:-1px}.df-character-display .character-hero{padding:60px 0 25px}.df-character-display .display-report{flex-direction:column;gap:10px;margin-top:20px}.df-character-display .display-roster{grid-template-columns:1fr;width:90%;gap:18px}.df-character-display .display-member{padding:18px}.df-character-display .display-portrait{height:240px;max-width:330px;margin:0 auto 18px}.df-character-display .display-host-offers button{width:100%;min-width:0}.df-character-display .display-fixture-controls{width:90%}.df-character-display .display-fixture-controls button{flex:1 1 150px}}
@media(max-width:360px){.df-character-display h1{font-size:33px}}
"#;
